package com.example.jalalidaily;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.*;import java.time.*;import org.json.*;
public final class Widgets{
 static void update(Context c,Class<?> cls,int layout,boolean notes){AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=m.getAppWidgetIds(new ComponentName(c,cls));int[] today=Jalali.fromGregorian(LocalDate.now());for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),layout);v.setTextViewText(R.id.date_text,Jalali.label(today));if(notes){StringBuilder s=new StringBuilder();JSONArray tasks=DayBundles.get(c,Jalali.key(today));for(int i=0;i<tasks.length();i++){JSONObject o=tasks.optJSONObject(i);if(o==null)continue;if(s.length()>0)s.append("\\n");s.append(o.optBoolean("done")?"✓ ":"○ ").append(o.optString("emoji","📝")).append(" ").append(o.optString("text"));}v.setTextViewText(R.id.notes_text,s.length()==0?"امروز یادداشتی ثبت نشده":s.toString());}PendingIntent p=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.date_text,p);if(notes)v.setOnClickPendingIntent(R.id.notes_text,p);m.updateAppWidget(id,v);}}
 static void refresh(Context c){update(c,DateWidget.class,R.layout.widget_date,false);update(c,NotesWidget.class,R.layout.widget_notes,true);}
}